const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a region for central Oklahoma (around Oklahoma City)
  const oklahomaGeom = ee.Geometry.Point(-97.51, 35.46).buffer(100000); // 100km radius
  // Define a region for northern Texas (around Dallas-Fort Worth)
  const texasGeom = ee.Geometry.Point(-97.03, 32.89).buffer(100000); // 100km radius

  const startDate = '2007-08-10';
  const endDate = '2007-08-21'; // End date is exclusive

  // 2. Data Acquisition & Check
  const trmmCollection = ee.ImageCollection('TRMM/3B42_Daily')
    .filterDate(startDate, endDate)
    .select('precipitation');

  const collectionSize = trmmCollection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No images found for the specified date range.");
    console.log("A"); // C1
    return;
  }
  console.log(`Image collection size: ${collectionSize}`);

  // 3. Processing
  // Calculate the total precipitation over the period for a cumulative value.
  const totalPrecipitation = trmmCollection.reduce(ee.Reducer.sum());

  const scale = 3000; // Use a coarse scale appropriate for TRMM to avoid timeout

  // 4. Calculation
  // Calculate the mean of the total precipitation for Oklahoma
  const okReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });
  const okStats = totalPrecipitation.reduceRegion({
    reducer: okReducer,
    geometry: oklahomaGeom,
    scale: scale,
    maxPixels: 1e9
  });

  // Calculate the mean of the total precipitation for Texas
  const txReducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });
  const texasStats = totalPrecipitation.reduceRegion({
    reducer: txReducer,
    geometry: texasGeom,
    scale: scale,
    maxPixels: 1e9
  });

  // Retrieve the results
  const okPrecip = okStats.get('precipitation_sum_mean').getInfo();
  const okPixels = okStats.get('precipitation_sum_count').getInfo();

  const texasPrecip = texasStats.get('precipitation_sum_mean').getInfo();
  const texasPixels = texasStats.get('precipitation_sum_count').getInfo();

  // 5. Validation & Final Answer
  if (okPixels === 0 || texasPixels === 0) {
    console.log("No valid pixels found in one or both regions after processing.");
    console.log(`Oklahoma Valid Pixels: ${okPixels}`);
    console.log(`Texas Valid Pixels: ${texasPixels}`);
    console.log("B"); // C2
    return;
  }

  if (okPrecip === null || texasPrecip === null || isNaN(okPrecip) || isNaN(texasPrecip)) {
    console.log("Calculation failed, result is null or NaN.");
    console.log(`Oklahoma Precipitation: ${okPrecip}`);
    console.log(`Texas Precipitation: ${texasPrecip}`);
    console.log("C3");
    return;
  }

  console.log(`Central Oklahoma Avg. Total Rainfall (mm): ${okPrecip.toFixed(2)}`);
  console.log(`Northern Texas Avg. Total Rainfall (mm): ${texasPrecip.toFixed(2)}`);

  if (okPrecip > texasPrecip) {
    console.log("B"); // A
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
